package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamTheoryColorBank4 {
    private const val T = "චිත්‍ර කලා මූලිකාංග, නිර්මාණ මූලධර්ම හා වර්ණ න්‍යාය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("මෝස්තර ඒකකයක් (Motif) කේන්ද්‍ර ලක්ෂ්‍යයක් වටා නිශ්චිත කෝණයකින් කරකවා නැවත නැවත ඇඳීමේ පරිවර්තන ක්‍රමය කුමක්ද?", "භ්‍රමණය කිරීම (Rotation)", "සරල ලිස්සා යාම (Translation)", "තාන අඳුරු කිරීම (Shading)", "වර්ණ ප්‍රතිවිරෝධනය (Contrast)", "මල් පෙති හෝ නෙළුම් මෝස්තර වෘත්තාකාරව සැකසීමේදී භ්‍රමණ පරිවර්තනය බහුලව යොදා ගැනේ."),
        q("රෙදිපිළි හා බිතුපත් මෝස්තර නිර්මාණයේදී ඊළඟ සිරස් තීරුව මූලික ඒකකයේ උසෙන් අඩක් පහළින් ඇරඹීමේ රටාව කුමක්ද?", "අර්ධ-පහළ පුනරාවර්තනය (Half-drop Repeat)", "සෘජු කොටු පුනරාවර්තනය (Block Repeat)", "කැඩපත් ප්‍රතිබිම්බ රටාව (Mirror Repeat)", "විකර්ණ ගැටුම් රටාව (Diagonal Clash)", "සරල කොටු රටාවේ ඒකාකාරී බව බිඳ ගලා යන ස්වාභාවික රිද්මයක් මැවීමට අර්ධ-පහළ පුනරාවර්තනය උපකාරී වේ."),
        q("මෝස්තර ඒකක තිරස් පේළි වශයෙන් තබන විට දෙවන පේළිය පළමු පේළියෙන් අඩක් පැත්තට මාරු කර තැබීමේ ක්‍රමය කුමක්ද?", "ගඩොල් පුනරාවර්තනය (Brick Repeat)", "වෘත්ත පුනරාවර්තනය (Radial Repeat)", "කේන්ද්‍රීය පදක්කම (Medallion Repeat)", "තනි වාටි රටාව (Linear Border)", "බිත්තියක ගඩොල් බැඳ ඇති පිළිවෙළ අනුව මෝස්තර විහිදුවන බැවින් මෙය ගඩොල් රටාව ලෙස හැඳින්වේ."),
        q("පෙට්ටියක, පිඟානක හෝ වස්ත්‍රයක පිටත දාරය දිගේ රේඛීයව ගලා යන සේ සකසන අලංකාර මෝස්තරය හඳුන්වන්නේ කුමන නමින්ද?", "වාටි මෝස්තරය (Border Design)", "සමස්ත තල මෝස්තරය (All-over Design)", "මැද පදක්කම් මෝස්තරය (Medallion)", "වියුක්ත සංයුතිය (Abstract Layout)", "වාටි මෝස්තරයක මුල හා අග එකිනෙකට ගැළපෙන පරිදි අඛණ්ඩ රේඛීය රිද්මයකින් සැලසුම් කෙරේ."),
        q("සෘජුකෝණාස්‍රාකාර රාමුවක වාටි මෝස්තරය අංශක 90කින් හරවා ඉදිරියට ගෙන යාම සඳහා විශේෂයෙන් නිර්මාණය කරන කොටස කුමක්ද?", "කොන් මෝස්තරය (Corner Motif)", "මධ්‍ය අක්ෂ රේඛාව (Central Axis)", "ක්ෂිතිජ රේඛාව (Horizon Line)", "අතුරුදන් ලක්ෂ්‍යය (Vanishing Point)", "වාටිය හැරෙන ස්ථානයේ රටාව කැඩී නොයා අලංකාරව හැඩගැන්වීමට විශේෂිත කොන් මෝස්තර යොදනු ලැබේ."),
        q("පිඟානක මැද, සිවිලිමක මැද හෝ පොත් කවරයක මැද වෘත්තාකාරව සමබරව සකසන ප්‍රධාන මෝස්තරය කුමක්ද?", "පදක්කම් මෝස්තරය (Medallion / Central Motif)", "අර්ධ-පහළ වාටි රටාව (Half-drop Border)", "තිරස් ගඩොල් රටාව (Brick Pattern)", "සෘජු අත්සන් මුද්‍රාව (Watermark)", "මැද ලක්ෂ්‍යයේ සිට පිටතට විහිදෙන රේඩියල් සමතුලිතතාව මෙවැනි නිර්මාණවල කැපී පෙනේ."),
        q("සම්ප්‍රදායික සිංහල මෝස්තර වර්ගීකරණයේදී 'ලියවැල' හා 'පලාපෙති' අයත් වන්නේ කුමන ප්‍රධාන මෝස්තර කාණ්ඩයටද?", "වෘක්ෂලතා හෙවත් උද්භිද කාණ්ඩයට", "ජ්‍යාමිතික රේඛා කාණ්ඩයට", "සත්ව හා පක්ෂි කාණ්ඩයට", "දේව හා අපරදිග කාණ්ඩයට", "මල්, වැල්, කොළ හා ගස්වැල් ශෛලිගත කොට සැකසූ සියලු මෝස්තර උද්භිද මෝස්තර ගණයට වැටේ."),
        q("දේශීය සම්ප්‍රදායික මෝස්තර අතර 'හංස පූට්ටුව', 'සිංහ රූපය' හා 'ගජසිංහ' අයත් වන කාණ්ඩය කුමක්ද?", "සත්ව කාණ්ඩයට (Fauna Motifs)", "ජ්‍යාමිතික කාණ්ඩයට (Geometric Motifs)", "ඛනිජ හා පාෂාණ කාණ්ඩයට", "රසායනික වර්ණ කාණ්ඩයට", "සැබෑ සතුන් මෙන්ම සතුන් කිහිප දෙනෙකුගේ අංග එක්කළ මිථ්‍යා සත්ව රූපද සාම්ප්‍රදායිකව අලංකරණයට ගැනිණි."),
        q("සිංහල ජ්‍යාමිතික මෝස්තර අතර එකිනෙක පැටලී අඛණ්ඩව ගමන් කරන ගෙතුම් හැඩැති මෝස්තරය හඳුන්වන්නේ කුමන නමින්ද?", "ලණුගැටය (Lanugataya)", "නෙළුම් මල (Lotus)", "හංස පූට්ටුව (Hansa Puttuwa)", "නාරිලතා (Narilatha)", "ලී කැටයම්, ඇත්දත් හා බිතුසිතුවම් වාටිවල ආරම්භයක් හෝ අවසානයක් නොමැති ගෙතුමක් ලෙස ලණුගැටය යෙදේ."),
        q("වෘත්තාකාර කුඩා මැණික් හෝ බිංදු පෙළක් මෙන් නැවත නැවත යෙදෙන සම්ප්‍රදායික සිංහල ජ්‍යාමිතික මෝස්තරය කුමක්ද?", "අරිම්බුව (Arimbuwa)", "කිඳුරු රූපය (Kindura)", "මකර තොරණ (Makara Torana)", "අන්නාසි මල (Annasi Mala)", "පන්සල් බිතුසිතුවම් රාමු වෙන් කිරීමේදී හා පලාපෙති වාටි අසල කුඩා වෘත්ත පෙළක් ලෙස අරිම්බුව යොදයි."),
        q("දියමන්ති හැඩැති හෝ ත්‍රිකෝණාකාර ජ්‍යාමිතික හැඩතල පෙළකින් සෑදුණු සම්ප්‍රදායික සිංහල වාටි මෝස්තරය කුමක්ද?", "කුන්දිරක්කන් (Kundirakkan)", "බෝපත (Bopatha)", "භේරුණ්ඩ පක්ෂියා (Bherunda)", "සැරපෙන්දියා (Serapendiya)", "ලී කැටයම් හා ලාක්ෂා කර්මාන්තයේදී සරල ජ්‍යාමිතික ත්‍රිකෝණ මාලාවක් ලෙස කුන්දිරක්කන් දක්නට ලැබේ."),
        q("සිංහල සාම්ප්‍රදායික මෝස්තර කලාවේ හතරැස් පෙට්ටියක් හෝ දියමන්ති හැඩයක් ඇතුළත මලක් තබා සකසන ජ්‍යාමිතික රටාව කුමක්ද?", "ගල්බිංදුව (Galbinduwa)", "කඩුපුල් මල (Kadupul)", "සිංහ මුහුණ (Lion Face)", "කිඹිහි මුහුණ (Kibihi Face)", "වාටි අලංකරණයේදී හා ගෘහ නිර්මාණ රාමුවල ශෛලිගත ජ්‍යාමිතික මැණික් කැබැල්ලක් සේ ගල්බිංදුව යෙදේ."),
        q("වක්‍ර වූ ජල රළ පෙළක් අනුකරණය කරමින් සම්ප්‍රදායික ශිල්පීන් නිර්මාණය කළ රිද්මයානුකූල වාටි මෝස්තරය කුමක්ද?", "දියරැල්ල (Diya Rella)", "පනා බේරුම (Pana Beruma)", "වෙල් ඉපනැල්ල (Wel Ipanella)", "තරු පොකුර (Star Cluster)", "ගංගා හා වැව්වල ජල චලනය සරල ශෛලිගත රේඛාවකින් දැක්වීම දියරැල්ල මෝස්තරයේ ලක්ෂණයයි."),
        q("සිංහල සැරසිලි කලාවේදී 'නෙළුම් මල' පදක්කමක් ලෙස ඇඳීමේදී පෙති බෙදීමට බහුලව යොදාගන්නා සමමිතික සංඛ්‍යා මොනවාද?", "පෙති 4, 8 හෝ 16", "පෙති 3, 7 හෝ 11", "පෙති 5, 9 හෝ 13", "පෙති 1, 2 හෝ 19", "වෘත්තය හතරට, අටට හෝ දහසයට සමානව බෙදා ඇඳීමෙන් සුමට රේඩියල් සමබරතාවක් ලබා ගනී."),
        q("ශ්‍රී ලාංකික මෝස්තර කලාවේදී බුද්ධත්වය හා පූජනීයත්වය සංකේතවත් කරමින් ද්විපාර්ශ්වික සමමිතියෙන් අඳින පත්‍ර මෝස්තරය කුමක්ද?", "බෝපත (Bopatha)", "වැටකේ මල (Wetakeiya)", "අන්නාසි මල (Annasi Mala)", "කතුරු මුරුංගා කොළය", "දොරටු, සඳකඩපහණ හා ධජ සැරසිලිවල බෝපත් හැඩය අතිශය ශෛලිගත සමමිතික මෝස්තරයක් ලෙස යෙදේ."),
        q("මහනුවර යුගයේ රෙදිපිළි හා විහාර චිත්‍රවල බහුලව දැකිය හැකි, බඹර තුඩු හෝ දෙදිශාවට විහිදෙන සුළි හැඩැති සැරසිල්ල කුමක්ද?", "සුළිය හා ලියපත", "සෘජු කොටු ජාලය", "නූතන බාර් කෝඩ් රටාව", "රෝම කොරින්තියන් කුළුණ", "වැල් හා මල්වල අග්‍රස්ථ අලංකරණය කිරීමට කරකැවුණු සුළි හැඩතල දේශීය කලාවේ බහුලය."),
        q("සිංහල කලා සම්ප්‍රදායේ හිස් දෙකක් හා එක් සිරුරක් සහිතව රාජකීය හා ආරක්ෂක සංකේතයක් ලෙස යොදාගන්නා පක්ෂි මෝස්තරය කුමක්ද?", "භේරුණ්ඩ පක්ෂියා", "හංස පූට්ටුව", "මොණර පැටවා", "කපුටු රූපය", "මහනුවර කොඩි හා ඇත්දත් කැටයම්වල දැකිය හැකි භේරුණ්ඩ පක්ෂියා බලය හා ද්විපාර්ශ්වික සමමිතිය පෙන්වයි."),
        q("ඇතෙකුගේ සොඬය, සිංහ පාද, මත්ස්‍ය වලිගය ආදී සත්ව අංග හතක් එක්කොට සාදන ලද සාම්ප්‍රදායික මිථ්‍යා මෝස්තරය කුමක්ද?", "මකර රූපය (Makara)", "නාරිලතා මල (Narilatha)", "ලණුගැටය (Lanugataya)", "පලාපෙති (Palapethi)", "විහාර තොරණ හා පඩිපෙළ කොරවක්ගල් අලංකරණයේදී විශ්වීය සමගිය සංකේතවත් කිරීමට මකරා නිමවේ."),
        q("සිතුවම්කරණයේදී වර්ණාවලිය (Spectrum) මුලින්ම වෘත්තාකාර වර්ණ චක්‍රයක් ලෙස සංවිධානය කළ විද්‍යාඥයා කවුද?", "ශ්‍රීමත් අයිසැක් නිව්ටන්", "ලියනාඩෝ ඩා වින්චි", "ගැලීලියෝ ගැලීලි", "ආකිමිඩීස්", "1666 දී ප්‍රිස්මයක් හරහා සුදු ආලෝකය වර්ණ හතකට බෙදා නිව්ටන් මුල්ම වර්ණ චක්‍රය සකස් කළේය."),
        q("වර්තමාන කලා අධ්‍යාපනයේ භාවිත වන වර්ණ 12කින් යුත් නූතන වර්ණ තරුව හා චක්‍රය සැකසූ බවුහවුස් ආචාර්යවරයා කවුද?", "ජොහැන්නස් ඉටන් (Johannes Itten)", "වින්සන්ට් වෑන් ගෝ", "ජැක්සන් පොලොක්", "ඔගස්ට් රොඩින්", "ප්‍රාථමික, ද්විතීයික හා තෘතීයික වර්ණ 12 පැහැදිලිව වර්ග කළ ඉටන්ගේ වර්ණ න්‍යාය පාසල් විෂය නිර්දේශයේ පදනමයි."),
        q("ඇල්බට් මන්සෙල්ගේ (Munsell Color System) වර්ණ පද්ධතිය තුළ ඕනෑම වර්ණයක් මැන බලන ප්‍රධාන මාන තුන මොනවාද?", "වර්ණ නාමය, තානය හා තීව්‍රතාව (Hue, Value, Chroma)", "දිග, පළල හා උස (Length, Width, Height)", "බර, ඝනත්වය හා උෂ්ණත්වය", "රේඛාව, හැඩය හා වයනය", "වර්ණයක් සතු පැහැය, එහි එළි-අඳුරු මට්ටම සහ සැර-මෘදු බව මන්සෙල් පද්ධතියෙන් නිවැරදිව දැක්වේ."),
        q("මූලික වර්ණවලට සුදු පැහැය වැඩිපුර මිශ්‍ර කර සකසා ගන්නා සෞම්‍ය හා සැහැල්ලු වර්ණ කාණ්ඩය හඳුන්වන්නේ කෙසේද?", "පැස්ටල් වර්ණ (Pastel / Tint Colors)", "පාංශු වර්ණ (Earth Colors)", "මූලික වර්ණ (Primary Colors)", "අඳුරු ඡායා (Deep Shades)", "ළමා කාමර, උත්සව ආරාධනා පත්‍ර හා සෞම්‍ය නිර්මාණ සඳහා පැස්ටල් වර්ණ බහුලව යොදා ගැනේ."),
        q("තද කළු හා පිරිසිදු සුදු පමණක් භාවිත කරමින් ආකෘතිවල සමබරතාව පෙන්වන ජපන් සංකල්පය කුමක්ද?", "නෝටන් (Notan)", "ඉකෙබානා (Ikebana)", "ඔරිගාමි (Origami)", "සුමි-ඊ (Sumi-e)", "'ආලෝකය-අඳුර' යන අරුත දෙන නෝටන් අභ්‍යාසය ධන සහ සෘණ අවකාශ අතර සමතුලිතතාව පුහුණු කරයි."),
        q("අළු හෝ උදාසීන වර්ණ පසුබිමක් මත තනි කුඩා දීප්තිමත් රතු වස්තුවක් තැබීමෙන් කුමන මූලධර්මය ක්‍රියාත්මක වේද?", "වර්ණ හුදෙකලා අවධාරණය (Focal Accent via Color)", "ඒකාකාරී සමබරතාව (Monotonous Balance)", "අඩු තාන ප්‍රතිවිරෝධය (Low Contrast)", "සෘජු කැඩපත් සමමිතිය (Mirror Symmetry)", "වටපිටාව මෘදු අවර්ණ වන විට තනි දීප්තිමත් වර්ණය ක්ෂණිකව නරඹන්නාගේ ප්‍රධාන නාභිය බවට පත්වේ."),
        q("සිතුවමක ඉදිරිපස වස්තූන් තියුණු දාරවලින්ද ඈත පසුබිම් වස්තූන් මෘදු බොඳ දාරවලින්ද ඇඳීමෙන් ලැබෙන ප්‍රතිඵලය කුමක්ද?", "ගැඹුර හා අවකාශ මායාව වැඩි වීම", "සියලු වස්තූන් පැතලි කොළ මෙන් පෙනීම", "සිතුවමේ සමබරතාව සම්පූර්ණයෙන් බිඳ වැටීම", "වර්ණ සියල්ල කළු පැහැයට හැරීම", "දාර පාලනය (Edge Control) මගින් පෙරබිම අවධාරණය කරමින් වායව දෘෂ්ටිකෝණය ශක්තිමත් කෙරේ."),
        q("වස්තුවක දාරය කැපී පෙනෙන පරිදි තියුණු රේඛාවකින් වෙන් වී තිබීම හා පසුබිමට මුසු වී යාම පිළිවෙළින් හඳුන්වන්නේ කෙසේද?", "තියුණු දාරය හා මෘදු දාරය (Hard & Soft Edge)", "උණුසුම් තානය හා සිසිල් තානය", "විශාල පරිමාණය හා කුඩා පරිමාණය", "රේඛීය රටාව හා මෝස්තර වාටිය", "අඳුරු තැන්වලදී දාර මෘදුව පසුබිමට මුසු වීම (Lost Edge) චිත්‍රයට ස්වාභාවික ජීවගුණයක් ලබා දෙයි."),
        q("ද්විමාන හැඩයක් ත්‍රිමාණ ආකෘතියක් බවට පත්වීමේදී ඒ සඳහා අනිවාර්යයෙන් එක් විය යුතු මූලිකාංගය කුමක්ද?", "තානය හෙවත් ආලෝක-අඳුරු (Value / Tone)", "පැතලි රතු පසුබිම (Flat Red Backdrop)", "වාටි මෝස්තරය (Linear Border)", "ලියවැල් රටාව (Vine Motif)", "වෘත්තයක් තාන හා සෙවණැලි යෙදීමෙන් පසු ත්‍රිමාණ ගෝලයක් ලෙස දිස්වේ."),
        q("සිලින්ඩරයක් හෝ මිනිස් අතක් වටා එහි වක්‍ර මතුපිට දිගේ අඳිනු ලබන සෙවණැලි හා ආකෘති පෙන්වන රේඛා මොනවාද?", "හරස් සමෝච්ඡ රේඛා (Cross-Contour Lines)", "තිරස් ක්ෂිතිජ රේඛා (Horizon Lines)", "සෘජු කතිර රේඛා (Grid Lines)", "කඩඉරි වාටි රේඛා (Border Lines)", "වස්තුවේ පිටත සීමාව පමණක් නොව එහි මතුපිට ගැඹුර හා නෙරා ඒම හරස් සමෝච්ඡ රේඛාවලින් පැහැදිලි වේ."),
        q("පින්සලේ ඉතා සුළු තීන්ත ප්‍රමාණයක් රඳවා රළු කඩදාසියක් මත සැහැල්ලුවෙන් ගෑමෙන් කඩතොලු සහිත වයනයක් මැවීම කුමක්ද?", "වියළි පින්සල් ක්‍රමය (Dry Brush / Scumbling)", "තෙත මත තෙත ක්‍රමය (Wet-on-Wet)", "විනිවිද සේදුම් ක්‍රමය (Flat Wash)", "ඉටි ප්‍රතිරෝධක ක්‍රමය (Wax Resist)", "ගස් පොතු, ගල් පර්වත හා ජලයේ දිලිසෙන ආලෝක රළ ඇඳීමට වියළි පින්සල් ක්‍රමය ඉතා ප්‍රයෝජනවත්ය."),
        q("ද්වි-අනුපූරක වර්ණ සංයෝජනය (Split Complementary) සෘජු අනුපූරක සංයෝජනයට වඩා ප්‍රසන්න වීමට හේතුව කුමක්ද?", "තද ප්‍රතිවිරෝධතාව ආරක්ෂා කරමින් වර්ණ ගැටුම් ආතතිය අඩු කිරීම", "වර්ණ චක්‍රයේ සියලුම වර්ණ කළු පැහැයට හැරවීම", "සුදු හා අළු පමණක් භාවිත කිරීමට ඉඩ දීම", "උණුසුම් වර්ණ සම්පූර්ණයෙන්ම ඉවත් කිරීම", "ප්‍රතිවිරුද්ධ වර්ණය වෙනුවට එහි දෙපස වර්ණ දෙක ගැනීමෙන් නෙතට ප්‍රියජනක සමතුලිතතාවක් ලැබේ."),
        q("තීව්‍ර වර්ණවලට අළු හෝ ප්‍රතිවිරුද්ධ වර්ණ ස්වල්පයක් මිශ්‍ර කර සකසන 'අඩු තීව්‍රතා වර්ණ' (Muted Colors) සංයුතියේදී ලබා දෙන ගුණය කුමක්ද?", "සන්සුන්, පරිණත හා ස්වාභාවික පෙනුමක් ලබා දීම", "දැඩි විද්‍යුත් නියොන් දීප්තියක් ඇති කිරීම", "සිතුවම කළු-සුදු තිත් බවට පත් කිරීම", "සියලු හැඩතල අතුරුදන් කර හැරීම", "පසුබිමට අඩු තීව්‍රතා වර්ණ යොදා ප්‍රධාන වස්තුවට පිරිසිදු වර්ණ තැබීමෙන් නාභිගත බව වැඩි වේ."),
        q("එකම තාන දීප්තියෙන් යුත් අතිශය තීව්‍ර අනුපූරක වර්ණ දෙකක් (උදා: දීප්තිමත් රතු හා කොළ) එකළඟ තැබූ විට දාරයේ ඇතිවන දෘශ්‍ය කම්පනය කුමක්ද?", "වර්ණ කම්පනය (Chromostereopsis / Color Vibration)", "වායව දෘෂ්ටිකෝණය (Aerial Perspective)", "කෙටි පෙනුම (Foreshortening)", "ඒකවර්ණ සේදුම (Monochrome Wash)", "දීප්තිමත් ප්‍රතිවිරුද්ධ වර්ණ සමාන අගයෙන් ගැටෙන විට ඇසට දිලිසෙන කම්පන ස්වභාවයක් දැනේ."),
        q("ආලෝක ප්‍රභවයක් ඉදිරියේ ඇති වස්තුවක අභ්‍යන්තර විස්තර නොමැතිව තනි අඳුරු පැතලි හැඩයක් ලෙස පෙනෙන රූපය කුමක්ද?", "සිල්වට් හෙවත් ඡායාරූප සටහන (Silhouette)", "ත්‍රිමාණ කැටයම් මූර්තිය (Relief Sculpture)", "චියාරෝස්කියුරෝ ආලේඛ්‍යය (Chiaroscuro)", "සමෝච්ඡ තාන පරිමාණය (Value Scale)", "හිරු බැස යන අහසක් ඉදිරිපිට කළු පැහැයෙන් පෙනෙන ගසක් සිල්වට් රූපයකට හොඳ නිදසුනකි."),
        q("මධ්‍ය අක්ෂය දෙපස ඇති අංග එකම කැඩපත් පිටපතක් නොවුවද හැඩයෙන් හා ප්‍රමාණයෙන් බොහෝ දුරට සමාන වීම කුමන සමමිතියද?", "සමීප සමමිතිය (Approximate Symmetry)", "අසමමිතික ගැටුම (Radical Asymmetry)", "ශුද්ධ රේඩියල් සමමිතිය (Pure Radial)", "වියුක්ත අසමතුලිතතාව (Imbalance)", "ඒකාකාරී ද්විපාර්ශ්වික සමමිතියට වඩා රසවත් බවක් හා ස්වාභාවික විවිධත්වයක් මෙයින් ලැබේ."),
        q("සැබෑ ලෝකයේ ප්‍රමාණයන් සිතාමතා වෙනස් කර (උදා: මිනිසෙකුට වඩා විශාල ඇපල් ගෙඩියක්) නරඹන්නා පුදුමයට පත් කිරීම කුමක්ද?", "පරිමාණ විකෘතිය (Scale Distortion)", "කැඩපත් සමමිතිය (Mirror Symmetry)", "වර්ණ විභේදනය (Color Division)", "වයන සමානතාව (Uniform Texture)", "සරියලිසම් හා නූතන නිර්මාණවලදී අදහසක් ප්‍රබල කිරීමට සාමාන්‍ය පරිමාණය මෙලෙස වෙනස් කෙරේ."),
        q("දෘශ්‍ය සමතුලිතතාවේදී සමාන ප්‍රමාණයේ සුදු හා කළු හැඩ දෙකක් සැලකුවහොත් වැඩි 'දෘශ්‍ය බරක්' (Visual Weight) දරන්නේ කුමක්ද?", "තද කළු හැඩය", "ලා සුදු හැඩය", "දෙකම සමාන බරකින් යුක්තය", "විකර්ණ රේඛා නොමැති හැඩය", "තද අඳුරු වර්ණ, තීව්‍ර රතු වැනි උණුසුම් වර්ණ හා සංකීර්ණ වයන සෑම විටම වැඩි දෘශ්‍ය බරක් දරයි."),
        q("සිංහල සාම්ප්‍රදායික වාටි මෝස්තර අතර ඉතා බහුලව දැකිය හැකි 'පලාපෙති' මෝස්තරය නිර්මාණය වී ඇත්තේ කුමන ස්වාභාවික අංගය ශෛලිගත කිරීමෙන්ද?", "නෙළුම් මලේ පෙති පෙළ", "ගංගාවේ ජල රළ පෙළ", "ඇත්දත් යුගලය", "මොණර පිල් කළඹ", "සඳකඩපහණ, විහාර බිතුසිතුවම් හා දැව කැටයම්වල දාර සැරසීමට ශෛලිගත නෙළුම් පෙති පෙළක් ලෙස පලාපෙති යෙදේ."),
        q("දේශීය කලා සම්ප්‍රදායේ කාන්තා රූපයක් මල් අත්තක හෝ ලියවැලක පිපුණු මලක් ලෙස නිර්මාණය කරන දුර්ලභ මෝස්තරය කුමක්ද?", "නාරිලතා මෝස්තරය (Narilatha)", "ලණුගැටය (Lanugataya)", "කුන්දිරක්කන් (Kundirakkan)", "අරිම්බුව (Arimbuwa)", "ඇම්බැක්කේ දේවාලයේ ලී කැටයම් හා ඇත්දත් කැටයම්වල නාරිලතා මෝස්තරය ඉතා කලාත්මකව දැකිය හැකිය."),
        q("විහාරස්ථානවල මකර තොරණ මුදුනේ ආරක්ෂක සංකේතයක් ලෙස යොදන බියකරු දේව/රක්ෂ මුහුණු මෝස්තරය කුමක්ද?", "කිඹිහි මුහුණ (Kibihi Muhuna)", "බෝපත (Bopatha)", "දියරැල්ල (Diya Rella)", "ගල්බිංදුව (Galbinduwa)", "උඩරට හා අනුරාධපුර කලා සම්ප්‍රදායේ උළුවහු හා තොරණ මුදුනේ ආරක්ෂාව හා ගාම්භීරත්වය සඳහා කිඹිහි මුහුණ නෙළයි."),
        q("නිර්මාණයක අනවශ්‍ය සැරසිලි හා අතිරික්ත විස්තර ඉවත් කර අවම අංග යොදා ප්‍රබල අදහසක් දීමේ මූලධර්මය කුමක්ද?", "සරල බව හෙවත් මිතව්‍යය (Economy / Simplicity)", "අතිශය සංකීර්ණත්වය (Over-ornamentation)", "අවුල් සහගත බව (Visual Clutter)", "ඒකාකාරී පුනරාවර්තනය (Redundancy)", "චිත්‍රයේ මූලික පණිවිඩයට හානි කරන අනවශ්‍ය කොටස් ඉවත් කිරීම නිර්මාණය වඩාත් ශක්තිමත් කරයි."),
        q("පැහැදිලි ලෙස දිග, පළල හා ගැඹුර යන මාන තුනම සහිත කලා කෘති වර්ගය හඳුන්වන්නේ කුමන නමින්ද?", "ත්‍රිමාණ කලා කෘති (Three-dimensional Art)", "ද්විමාන චිත්‍ර කෘති (Two-dimensional Art)", "ඒකමාන රේඛා සටහන් (One-dimensional Art)", "ඩිජිටල් පැතලි රූප (Flat Graphics)", "මූර්ති, මැටි බඳුන් හා වාස්තු නිර්මාණ සැබෑ අවකාශයේ මාන තුනෙන්ම ස්පර්ශ කළ හැකි කෘති වේ."),
        q("තද වර්ණයක් පැහැදිලිව කැපී පෙනෙන පරිදි පෙන්වීමට ඊට යාබදව සැහැල්ලු හෝ උදාසීන අළු වර්ණයක් තැබීමෙන් ඇතිවන්නේ කුමක්ද?", "තීව්‍රතා ප්‍රතිවිරෝධතාව (Saturation Contrast)", "උෂ්ණත්ව සමානතාව (Temperature Harmony)", "රේඩියල් භ්‍රමණය (Radial Rotation)", "සමීප වර්ණ මිශ්‍රණය (Analogous Blend)", "අළු පසුබිමක තැබූ දීප්තිමත් කහ හෝ තැඹිලි පැහැය එහි සැබෑ තත්ත්වයටත් වඩා දීප්තිමත්ව දිස්වේ."),
        q("පාසල් චිත්‍ර අභ්‍යාසයේදී 'කළු සුදු සේදුම් ක්‍රමය' (Monochrome Wash) පුහුණු කිරීමෙන් සිසුවාට ලැබෙන ප්‍රධාන ප්‍රයෝජනය කුමක්ද?", "වර්ණවල බලපෑමෙන් තොරව ආලෝක-අඳුරු තානය පාලනය කිරීම", "වර්ණ චක්‍රයේ සියලු ද්විතීයික වර්ණ පාඩම් කිරීම", "රෙදි මත ඉටි බතික් සායම් පෙඟවීම", "තෙල් සායම් පිහි භාවිතය ප්‍රගුණ කිරීම", "තනි කළු හෝ සෙපියා වර්ණයෙන් ජලය මිශ්‍ර කර චිත්‍ර ඇඳීම තාන සමතුලිතතාව අවබෝධ කරවයි."),
        q("චිත්‍රයක රූප රාමුවේ එක් දාරයකින් වස්තුවක් අඩක් කැපී යන සේ ඇඳීම (Cropping) මගින් ලැබෙන දෘශ්‍ය හැඟීම කුමක්ද?", "සිතුවම රාමුවෙන් ඔබ්බටද විහිදෙන බව හා සමීප බව", "වස්තුව කැඩී බිඳී ගොස් ඇති අසම්පූර්ණ බව", "සිසුවාට කඩදාසියේ ඉඩ මදි වූ බව", "චිත්‍රයේ මධ්‍ය අක්ෂ සමමිතිය සම්පූර්ණ වීම", "ඡායාරූප කලාව හා ඩෙගාස්ගේ සිතුවම් මෙන් ක්‍රොපිං ක්‍රමය සංයුතියට සජීවී හා නූතන පෙනුමක් දෙයි."),
        q("වර්ණ චක්‍රයේ ප්‍රාථමික වර්ණ දෙකක් අසමාන ප්‍රමාණවලින් (උදා: රතු වැඩිපුර + කහ ස්වල්පයක්) මිශ්‍ර කළ විට ලැබෙන්නේ කුමක්ද?", "තෘතීයික වර්ණයක් (රතු-තැඹිලි)", "ශුද්ධ උදාසීන කළු වර්ණයක්", "සිසිල් අහස් නිල් වර්ණයක්", "ප්‍රතිවිරුද්ධ කොළ වර්ණයක්", "ප්‍රාථමික වර්ණයක් සමඟ යාබද ද්විතීයික වර්ණ ගුණය වැඩි වීමෙන් තෘතීයික අතරමැදි වර්ණ උපදී."),
        q("චිත්‍ර සංයුතියේදී එකම ප්‍රමාණයේ හා එකම හැඩයේ වස්තූන් හරි මැදින් පෙළට තැබීමෙන් ඇති විය හැකි දුර්වලතාව කුමක්ද?", "ඒකාකාරී නීරස බව (Monotony) ඇති වීම", "අධික නාට්‍යමය චලනයක් හට ගැනීම", "පසුබිම ඉදිරියට පැනීම", "වර්ණ සියල්ල වියළී ඉරි තැලීම", "ඒකාබද්ධතාව සමඟ ප්‍රමාණ, වර්ණ හා පරතරවල විවිධත්වයක් (Variety) තිබීමෙන් චිත්‍රය ප්‍රාණවත් වේ."),
        q("නිශ්චල ජීව චිත්‍රයක (Still Life) පලතුරු බඳුනක් හා කෝප්පයක් අතර යම් ප්‍රමාණයක් එකිනෙක ගැටී හෝ වැසී පිහිටීම නිර්දේශ කරන්නේ ඇයි?", "වස්තූන් වෙන්ව පාවෙමින් නොතිබී එකම කණ්ඩායමක් ලෙස බැඳීමට", "චිත්‍රය අඳින කාලය අඩකින් අඩු කර ගැනීමට", "පසුබිම් මේස රෙද්ද සම්පූර්ණයෙන් මැකීමට", "සෑම වස්තුවක්ම එකම පැතලි හැඩයක් බවට හැරවීමට", "එකිනෙක වැසීම හා කණ්ඩායම් ගත කිරීම (Grouping) නිශ්චල ජීව සංයුතිය ශක්තිමත් කරයි."),
        q("නිර්මාණ මූලධර්ම අතර 'රිද්මය' (Rhythm) යනු සංගීතයේ තාලය මෙන් දෘශ්‍ය කලාවේ කුමන කාර්යයක් ඉටු කරයිද?", "නරඹන්නාගේ ඇස සංවිධානාත්මකව චිත්‍රය පුරා ගමන් කරවීම", "චිත්‍රය නිහඬව එක තැනම කැටි කර තැබීම", "වර්ණ චක්‍රයේ වර්ණ ගණන දෙකකට සීමා කිරීම", "කැන්වසයේ ප්‍රමාණය මැන බැලීම", "හැඩතල, වර්ණ හා අන්තරයන්ගේ ක්‍රමවත් පුනරාවර්තනය දෘශ්‍ය සංගීතයක් මෙන් රිද්මය ජනිත කරයි."),
        q("සම්ප්‍රදායික ශ්‍රී ලාංකේය මෝස්තරයක් නිර්මාණය කිරීමේදී මලක හෝ කොළයක පිටත දාර රේඛා ක්‍රමානුකූලව සකස් කිරීමේදී සලකන්නේ කුමක්ද?", "සමබරතාව, රිද්මය හා රේඛා ලාලිත්‍යය", "ඡායාරූපමය ත්‍රිමාණ සෙවණැලි පමණක්", "කඩදාසියේ බර හා ඝනකම පමණක්", "අවුල් සහගත අහඹු පින්සල් පහරවල්", "දේශීය මෝස්තර සැමවිටම නිශ්චිත රිද්මයානුකූල වක්‍ර රේඛා හා අලංකාර සමානුපාත මත ගොඩනැගේ."),
        q("අ.පො.ස. (සා.පෙළ) චිත්‍ර කලා විෂයේ 'මූලිකාංග හා මූලධර්ම' ප්‍රගුණ කිරීම ප්‍රායෝගික නිර්මාණයේදී උපකාරී වන්නේ කෙසේද?", "විද්‍යාත්මක හා කලාත්මක ලෙස සාර්ථක සංයුතියක් ගොඩනැගීමට", "වෙනත් අයගේ කෘති යන්ත්‍ර මෙන් පිටපත් කිරීමට පමණක්", "තීන්ත වර්ග නාස්ති නොකර අඩු වර්ණ ගණනක් ගෑමට පමණක්", "කලා ඉතිහාස දින වකවානු කටපාඩම් කිරීමට පමණක්", "රේඛා, හැඩ, වර්ණ හා සමතුලිතතා මූලධර්ම දැනුම සෑම චිත්‍ර, මෝස්තර හා මූර්ති නිර්මාණයකම පදනමයි.")
    )
}
